long long countWays(int n, int m) {
    vector<long long> dp(n+1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= min(i, m); j++) {
            dp[i] = (dp[i] + dp[i-j]) % MOD;
        }
    }
    return dp[n];
}

