#include <bits/stdc++.h>
using namespace std;

static const int MOD = 100000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Maximum consecutive presses that can form one character for each key.
    // 0,1 have 5 chars; 2 has 4; 3-9 have 3.
    int lim[10] = {5, 5, 4, 3, 3, 3, 3, 3, 3, 3};

    string s;
    while (cin >> s && s != "#") {
        int n = (int)s.size();
        vector<int> dp(n + 1, 0);
        dp[0] = 1;

        for (int i = 1; i <= n; ++i) {
            char c = s[i - 1];
            int d = c - '0';
            int maxlen = lim[d];

            for (int len = 1; len <= maxlen && i - len >= 0; ++len) {
                bool ok = true;
                for (int k = i - len; k < i; ++k) {
                    if (s[k] != c) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break; // longer lengths also impossible
                dp[i] += dp[i - len];
                if (dp[i] >= MOD) dp[i] -= MOD;
            }
        }

        cout << dp[n] % MOD << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 100000007;
    // Number of characters for each digit (0-9)
    static final int[] pressCount = {1, 5, 3, 3, 3, 3, 3, 4, 3, 4};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while (!(line = br.readLine()).equals("#")) {
            System.out.println(solve(line));
        }
    }

    static long solve(String s) {
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            int digit = s.charAt(i - 1) - '0';
            int maxPress = pressCount[digit];
            // Try all possible lengths of same digit ending at i
            for (int len = 1; len <= maxPress && i - len >= 0; len++) {
                if (s.charAt(i - len) - '0' != digit) break;
                dp[i] = (dp[i] + dp[i - len]) % MOD;
            }
        }
        return dp[n];
    }
}

