public class Main {
    static final long MOD = 100000007L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.equals("#")) break;
            System.out.println(solve(line));
        }
    }

    static long solve(String s) {
        if (s.isEmpty()) return 1;
        long result = 1;
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int j = i;
            while (j < s.length() && s.charAt(j) == c) j++;
            int runLen = j - i;
            int m = getMax(c);
            long ways = countWays(runLen, m);
            result = result * ways % MOD;
            i = j;
        }
        return result;
    }

    static int getMax(char c) {
        if (c == '8' || c == '0') return 3;
        return 5;
    }

    static long countWays(int k, int m) {
        long[] dp = new long[k + 1];
        dp[0] = 1;
        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= Math.min(i, m); j++) {
                dp[i] = (dp[i] + dp[i - j]) % MOD;
            }
        }
        return dp[k];
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 100000007;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        String s;
        while ((s = br.readLine()) != null) {
            if (s.equals("#")) break;
            out.append(solve(s)).append('\n');
        }

        System.out.print(out.toString());
    }

    static int solve(String s) {
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            char d = s.charAt(i - 1);

            // A group can only consist of repeated same digit.
            // Maximum group length depends on the digit:
            // 1..5 : 5 chars
            // 6..0 : 4 chars
            int limit = (d >= '1' && d <= '5') ? 5 : 4;

            long ways = 0;
            for (int len = 1; len <= limit && i - len >= 0; len++) {
                if (s.charAt(i - len) != d) break;
                ways += dp[i - len];
                if (ways >= MOD) ways %= MOD;
            }
            dp[i] = ways % MOD;
        }

        return (int) dp[n];
    }
}

