long long ways[100001];

void precompute() {
    ways[0] = 1;
    for (int i = 1; i <= 100000; i++) {
        ways[i] = 0;
        for (int k = 1; k <= 5 && k <= i; k++) {
            ways[i] = (ways[i] + ways[i-k]) % MOD;
        }
    }
}

int main() {
