            line[--len] = '\0';
        }

        if (len == 1 && line[0] == '#') break;
        if (len == 0) continue;

        long long result = 1;
        int i = 0;
        while (i < len) {
            char c = line[i];
            int j = i;
            while (j < len && line[j] == c) j++;
            int run = j - i;
            result = (result * ways[run]) % MOD;
            i = j;
        }

        printf("%lld\n", result);
    }

    return 0;
}

#include <stdio.h>
#include <string.h>

#define MOD 100000007
#define MAXN 100000 + 5

/*
Phone keypad style:
1: あ い う え お        -> 5 letters
2: か き く け こ        -> 5
3: さ し す せ そ        -> 5
4: た ち つ て と        -> 5
5: な に ぬ ね の        -> 5
6: は ひ ふ へ ほ        -> 5
7: ま み む め も        -> 5
8: や (ゆ) よ            -> 3
9: ら り る れ ろ        -> 5
0: わ を ん             -> 3

If the same key is pressed repeatedly, the intended grouping may be split because of delays.
So for each maximal run of the same digit of length L, the number of interpretations
is the number of ways to partition L into parts of size 1..K, where K depends on the digit:
K = 5 for digits 1..7,9
K = 3 for digits 0,8

Total answer = product over runs.
*/

static char s[MAXN];
static int dp3[MAXN], dp5[MAXN];

int main(void) {
    /* Precompute compositions with parts up to 3 and 5 */
    dp3[0] = dp5[0] = 1;
    for (int i = 1; i < MAXN; i++) {
        long long v = 0;
        for (int j = 1; j <= 3; j++) {
            if (i - j >= 0) v += dp3[i - j];
        }
        dp3[i] = (int)(v % MOD);

        v = 0;
        for (int j = 1; j <= 5; j++) {
            if (i - j >= 0) v += dp5[i - j];
        }
        dp5[i] = (int)(v % MOD);
    }

    while (scanf("%s", s) == 1) {
        if (strcmp(s, "#") == 0) break;

        int n = (int)strlen(s);
        long long ans = 1;

        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            int len = j - i;
            char c = s[i];

            if (c == '0' || c == '8') {
                ans = (ans * dp3[len]) % MOD;
            } else {
                ans = (ans * dp5[len]) % MOD;
            }

            i = j;
        }

        printf("%lld\n", ans % MOD);
    }

    return 0;
}
